.is-vertical .travel-orbit-scene { touch-action: pan-x; }
.is-vertical .travel-orbit-photo { width: var(--orbit-photo-width); height: auto; max-height: var(--orbit-photo-height); object-fit: contain; }
.is-vertical .travel-orbit-controls { inset: 14px auto max(14px, env(safe-area-inset-bottom)) 50%; height: auto; width: 0; flex-direction: column; }
.is-vertical .travel-orbit-controls button { width: 104px; height: 64px; flex: 0 0 64px; }
@media (hover:hover) and (pointer:fine) {
  .travel-orbit-controls button { opacity: 0; }
  .travel-orbit:hover .travel-orbit-controls button,.travel-orbit-controls:focus-within button { opacity: .88; }
  .travel-orbit-controls button:hover { opacity: 1; }
  .travel-orbit-controls .is-previous:hover svg,.travel-orbit-controls .is-previous:hover::before { transform: rotate(var(--orbit-control-angle)) translateX(-11px); }
  .travel-orbit-controls .is-next:hover svg,.travel-orbit-controls .is-next:hover::before { transform: rotate(var(--orbit-control-angle)) translateX(11px); }
}
@media (max-width:760px) {
  .travel-orbit-photo { height: min(350px, 52dvh); }
  .travel-orbit-controls button { width: 44px; }
  .travel-orbit-controls svg,.travel-orbit-controls button::before { width: 60px; height: 60px; }
}
